-- L13-A1-character-facts.rollback.sql (lot A1, 2026-10-30; generated by scripts/anime/a1/gen-sql.mjs, do not edit by hand)
--
-- What:   undoes L13: deletes the rows of the 50 launch series from character_facts and series_facts, and their entity_sources rows of the six fields. Refused once the game otakudle has a play.
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $a1$
declare plays bigint := 0;
begin
  if to_regclass('public.dle_plays') is not null then
    execute $q$select count(*) from public.dle_plays where game_id = 'otakudle'$q$ into plays;
  end if;
  if plays > 0 then
    raise exception 'L13 rollback refused: the game otakudle has a play';
  end if;
end $a1$;

delete from public.character_facts where character_id in (select c.id from public.characters c join public.groups g on g.id = c.group_id where g.site_id = 'anime' and g.slug in ('apothecary-diaries', 'attack-on-titan', 'black-clover', 'bleach', 'blue-lock', 'bocchi-the-rock', 'chainsaw-man', 'code-geass', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'detective-conan', 'dr-stone', 'dragon-ball', 'evangelion', 'fairy-tail', 'frieren', 'fruits-basket', 'fullmetal-alchemist', 'gintama', 'haikyu', 'hunter-x-hunter', 'inuyasha', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaguya-sama-love-is-war', 'kaiju-no-8', 'mob-psycho-100', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 're-zero', 'sailor-moon', 'sakamoto-days', 'slam-dunk', 'solo-leveling', 'spy-x-family', 'steins-gate', 'sword-art-online', 'that-time-i-got-reincarnated-as-a-slime', 'tokyo-ghoul', 'tokyo-revengers', 'tower-of-god', 'vinland-saga', 'violet-evergarden'));
